import sys


def classify_growth(t1, t2):
    if t2 == t1:
        return 0
    if t2 == 2 * t1:
        return 1
    if t2 == 4 * t1:
        return 2
    if t2 == t1 + 1:
        return 3
    return 9


data = sys.stdin.read().split()
sys.stdout.write(str(classify_growth(int(data[0]), int(data[1]))) + "\n")

import sys


def visit_count(n):
    total = 0
    for i in range(n):
        for j in range(i + 1):
            total += 1
    return total


n = int(sys.stdin.read().strip())
sys.stdout.write(str(visit_count(n)) + "\n")
